```java
interface Printable {
    void print();
}

interface Loggable {
    void log();
}

interface Combined extends Printable, Loggable {
}

class Reporter implements Combined {
    public void print() {
        System.out.print("P");
    }
    public void log() {
        System.out.print("L");
    }
}

public class Main {
    public static void main(String[] args) {
        Combined c = new Reporter();
        c.print();
        c.log();
    }
}
```

